async function readJson<T=any>(response:Response):Promise<T>{
 const body=await response.text();
 if(!body.trim())throw Error(response.ok?'The server returned an empty response.':`Request failed (${response.status}) with an empty response.`);
 let data:T;
 try{data=JSON.parse(body) as T}catch{throw Error(response.ok?'The server returned an invalid response.':`Request failed (${response.status}). Check that the API server is running.`)}
 if(!response.ok)throw Error((data as any)?.error||`Request failed (${response.status}).`);
 return data;
}
